  "dizi.unauthenticated": {
    "title": "Your session has ended",
    "when": "Missing or expired token (Keycloak, P0-205)",
    "client": "Re-authenticate and replay: the outbox survives a session ending"
  },
  "dizi.unavailable": {
    "title": "The cloud is unreachable",
    "when": "The database, or the uplink, or the cloud tier is down",
    "client": "Keep the write queued and keep working; the sync pill already says how long it has been"
  },
